// Replaces the MainActivity generated by `tauri android init` in CI, which keeps the
// generated package line and drops this one.
package express.suttacentral

import android.content.res.Configuration
import android.os.Bundle
import android.view.View
import androidx.activity.enableEdgeToEdge
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MainActivity : TauriActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        enableEdgeToEdge()
        super.onCreate(savedInstanceState)

        // Edge-to-edge draws the webview under the status and navigation bars, and older
        // WebViews don't report safe-area insets to CSS, so pad the content view natively.
        val content = findViewById<View>(android.R.id.content)
        applyBackground(content, resources.configuration)
        ViewCompat.setOnApplyWindowInsetsListener(content) { view, insets ->
            // ime() too, as edge-to-edge stops the keyboard from resizing the window
            val bars = insets.getInsets(
                WindowInsetsCompat.Type.systemBars() or
                    WindowInsetsCompat.Type.displayCutout() or
                    WindowInsetsCompat.Type.ime()
            )
            view.setPadding(bars.left, bars.top, bars.right, bars.bottom)
            WindowInsetsCompat.CONSUMED
        }
    }

    // The manifest handles uiMode itself, so a light/dark switch lands here rather than
    // recreating the activity
    override fun onConfigurationChanged(newConfig: Configuration) {
        super.onConfigurationChanged(newConfig)
        enableEdgeToEdge() // re-picks light or dark system bar icons
        applyBackground(findViewById(android.R.id.content), newConfig)
    }

    // The site's page background (styles/styles.css), so the padded bar areas blend in
    private fun applyBackground(view: View, config: Configuration) {
        val night =
            (config.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
        view.setBackgroundColor(if (night) 0xFF282828.toInt() else 0xFFFAF9F6.toInt())
    }
}
